/* ===== UNIT 6 DATA (answer positions shuffled) ===== */
LBC['5.0']={"obj":["Hiểu ý chính và chi tiết trong cuộc phỏng vấn về nội quy trường học","Dùng từ vựng về nội quy và hành vi ở trường","Phân biệt have to, mustn’t và don’t have to","Dùng bị động + to-infinitive: be allowed / expected / encouraged / supposed to","Thảo luận và đóng vai phỏng vấn về nội quy trường mình"],"vocab":[["strict","nghiêm khắc, nghiêm ngặt","adj"],["good behaviour","hành vi tốt","n"],["respect","sự tôn trọng; tôn trọng","n/v"],["break the rules","vi phạm nội quy","v"],["get into trouble","gặp rắc rối, bị khiển trách","v"],["get a detention","bị phạt ở lại trường","v"],["stay behind after school","ở lại sau giờ học","v"]],"gram":[{"t":"Passive + to-infinitive (allow, encourage, expect, suppose)","r":"Subject + be + past participle + to + verb. Dùng để nói về quy định, kỳ vọng và điều được phép làm.","ex":["At lunch, we’re expected to serve the food and drinks for each other.","We’re not allowed to wear earphones.","Are you supposed to know all the rules?"]},{"t":"have to / mustn’t / don’t have to","r":"have to = bắt buộc phải làm. mustn’t = bị cấm. don’t have to = không cần thiết (không bắt buộc). Don’t have to KHÔNG đồng nghĩa với mustn’t.","ex":["They have to wear the correct school uniform.","They mustn’t talk in the corridors.","They don’t have to have lunch in the school canteen."]}],"tips":["Sau be allowed / expected / encouraged / supposed luôn dùng to + động từ nguyên mẫu.","You don’t have to bring lunch ≠ You mustn’t eat in the library.","Đáp án phần nghe phải dựa vào audio của sách, không đoán."]};
LBC['5.1']={"obj":["Hiểu ý chính và chi tiết của bài báo về gia đình và phương pháp kaizen","Hiểu và dùng từ vựng về việc nhà và quản lý kinh doanh","Nhận biết passive infinitive: to be + past participle","Thảo luận cách áp dụng cải tiến liên tục trong gia đình và công việc"],"vocab":[["hectic","bận rộn, tất bật","adj"],["household chores","việc nhà","n"],["strategy","chiến lược, cách tiếp cận có kế hoạch","n"],["knots","“nút thắt”: những vấn đề làm chậm quá trình (trong bài: the problems that were slowing things down)","n"],["pitch in","chung tay giúp đỡ","v"],["resentment","sự bất mãn, oán giận","n"],["efficiency","hiệu quả, hiệu suất","n"],["employee","nhân viên","n"],["executive","quản lý cấp cao","n"],["management","sự quản lý","n"],["practice","phương pháp, cách thực hành","n"],["process","quy trình","n"],["productivity","năng suất","n"],["schedule","lịch trình","n"],["set goals","đặt mục tiêu","v"],["system","hệ thống","n"],["workload","khối lượng công việc","n"]],"gram":[{"t":"Passive infinitive: to be + past participle","r":"Dùng khi nói về việc cần được làm; trọng tâm là công việc hoặc kết quả, không phải người làm.","ex":["The house was in chaos, with piles of washing to be done and clothes to be ironed.","There is a lot of washing to be done.","These clothes need to be ironed."]}],"tips":["Active: to do the washing. Passive: to be done.","Sau to be luôn dùng quá khứ phân từ (V3): to be washed, to be ironed.","Câu hỏi E–G cần suy luận: nói rõ đâu là suy luận của bạn, đâu là thông tin trong bài báo."]};
LBC['5.2']={"obj":["Khám phá cách các gia đình đặt ra quy tắc và xin phép","Hiểu 5 expressions về quy tắc gia đình","Nghe để tìm quy tắc và những việc cần xin phép (Track 34, 35)","Tường thuật câu hỏi và lời nói: if / whether, wh-questions, said, told","Đóng vai xin phép và tường thuật hội thoại"],"vocab":[["a ban on (phones at the table)","lệnh cấm (dùng điện thoại khi ăn)","n"],["a phone-free zone","khu vực không dùng điện thoại","n"],["screen time","thời gian sử dụng màn hình","n"],["make your bed","dọn giường","v"],["ask permission","xin phép","v"]],"gram":[{"t":"Reported questions and statements","r":"Yes/No: asked + if / whether. Wh-: giữ từ để hỏi nhưng dùng trật tự câu kể (subject + verb). Statements: said (không cần tân ngữ); told + người + (to-V).","ex":["Alisha asked if / whether she could stay up late.","Raheem’s dad asked Raheem whose house he was going to.","Alisha said she wanted to watch the football match.","Raheem’s dad told him to bring them back."]}],"tips":["Không dùng trật tự câu hỏi: whose house he was going to (không phải was he going to).","Tell luôn cần tân ngữ: told him / told Raheem. Said me là sai.","Phần nghe Track 34 và 35 đã thay bằng hai video YouTube (xem link trong bài); đáp án dựa vào lời thoại video."]};
LBC['5.3']={"obj":["Hiểu moral dilemma là gì","Đọc ba tình huống và mô tả thái độ của người viết","Dùng third conditional: If + past perfect, would / could / might have + V3","Dùng if only + past perfect để diễn tả tiếc nuối","Nghe (Track 36) và thảo luận bạn sẽ làm gì"],"vocab":[["moral dilemma","tình huống khó xử về đạo đức","n"],["responsible","có trách nhiệm","adj"],["regret","sự hối tiếc; hối tiếc","n/v"],["keep a secret","giữ bí mật","v"],["persuade","thuyết phục","v"],["go back to …","quay lại …","v"]],"gram":[{"t":"Third conditional","r":"Nói về tình huống tưởng tượng trong quá khứ (điều đã không xảy ra). If + had + V3, would have + V3. Có thể đảo vế. Dùng could have / might have để nói khả năng.","ex":["If someone had lost the money, they would have gone back to look for it.","What would you have done if you had been in my position?","If I had known, I might have helped."]},{"t":"If only + past perfect","r":"If only + subject + had + V3 diễn tả sự tiếc nuối về điều đã không làm.","ex":["If only I had told a teacher about the problem with the other girls, the teacher would have sorted it out."]}],"tips":["Sai: If I would have known. Đúng: If I had known.","If only I had told the teacher! = nhấn mạnh sự tiếc nuối.","Track 36 đã thay bằng một video về tình huống nhặt được tiền; ghi lại điều người nói thật sự nói."]};
LBC['5.4']={"obj":["Hiểu những việc được phép làm ở các độ tuổi khác nhau (danh sách UK trong sách)","Dùng 7 collocations về quyền công dân","Bày tỏ và bảo vệ ý kiến về giới hạn độ tuổi","Nghiên cứu và viết danh sách quyền của thanh thiếu niên ở Việt Nam","So sánh hai quốc gia"],"vocab":[["work part-time / full-time","làm việc bán thời gian / toàn thời gian","v"],["leave home","ra ở riêng","v"],["get married","kết hôn","v"],["join the army","nhập ngũ","v"],["open a bank account","mở tài khoản ngân hàng","v"],["do jury service","làm bồi thẩm đoàn","v"],["give blood","hiến máu","v"],["mature","trưởng thành, chín chắn","adj"],["responsibility","trách nhiệm","n"]],"gram":[{"t":"Collocations","r":"Collocation là các từ thường đi cùng nhau. Học theo cụm: open a bank account (không phải make a bank account).","ex":["At 13 you can open your own bank account.","At 18 you can vote, get married and give blood."]},{"t":"Giving opinions & agreeing/disagreeing","r":"Dùng mẫu câu có lý do: I think … because … / I see your point, but … / It depends on the individual, not just age.","ex":["I think it is reasonable because …","I see your point, but …"]}],"tips":["Danh sách độ tuổi của UK là nội dung trong sách, không phải hướng dẫn pháp lý cập nhật.","Không mặc định Việt Nam giống UK: tra nguồn chính thức và ghi rõ điều kiện.","Dùng according to the source / in general / subject to conditions khi có ngoại lệ."]};
LBC['5.5']={"obj":["So sánh hai lời khai và tìm điểm không nhất quán","Dùng past continuous và past simple để kể lại một tai nạn","Dùng was/were going to + verb để nói về ý định trong quá khứ","Đưa ra ý kiến có lý do về trách nhiệm trong vụ tai nạn"],"vocab":[["witness","nhân chứng","n"],["statement","lời khai","n"],["parked car","xe ô tô đỗ bên đường","n"],["wing mirror","gương chiếu hậu bên ngoài xe","n"],["selfie stick","gậy tự sướng","n"],["handlebars","ghi đông xe đạp","n"],["crash into","đâm vào","v"],["fall off","ngã khỏi","v"],["accident","tai nạn","n"]],"gram":[{"t":"Past continuous & past simple","r":"Past continuous (was/were + V-ing) cho hành động đang diễn ra / bối cảnh. Past simple cho sự việc xen vào. Mẫu: past continuous + when + past simple.","ex":["I was driving along the road.","The cyclist was looking at his phone when someone opened the car door.","When someone opened the car door, the cyclist was looking at his phone."]},{"t":"was / were going to + verb","r":"Diễn tả ý định trong quá khứ, dù có thể không xảy ra.","ex":["He had his arm out to show that he was going to turn left.","I was going to get my bag when a cyclist crashed into the door."]}],"tips":["Chi tiết khác nhau không tự động có nghĩa là nhân chứng nói dối.","Phân biệt evidence (lời khai) và opinion (ý kiến cá nhân).","Không kết luận chắc chắn khi hai lời khai mâu thuẫn."]};
LBC['5.6']={"obj":["Xác định người nhận và mục đích của một email","Nhận biết giọng văn lịch sự nhưng thân thiện","Trả lời theo đúng thứ tự các câu hỏi trong email gốc","Dùng cách diễn đạt phù hợp để hỏi, trả lời và nêu ý kiến","Viết email trả lời về nội quy trường mình"],"vocab":[["I would be very grateful if you could …","Tôi rất biết ơn nếu bạn có thể … (lịch sự)","phr"],["I’d appreciate any information …","Tôi rất trân trọng mọi thông tin …","phr"],["Thank you for your email.","Cảm ơn email của bạn.","phr"],["I would be delighted to …","Tôi rất vui được …","phr"],["When it comes to …","Khi nói đến …","phr"],["Overall, I think …","Nhìn chung, tôi nghĩ …","phr"],["I hope my answers are helpful.","Hy vọng câu trả lời của tôi hữu ích.","phr"],["Best wishes,","Trân trọng / Chúc bạn mọi điều tốt đẹp,","phr"]],"gram":[{"t":"Polite but friendly email","r":"Mở đầu thân thiện, trả lời theo thứ tự câu hỏi, chia đoạn ngắn theo chủ đề, nêu ý kiến ở cuối và kết thúc lịch sự.","ex":["Thank you for your email. I would be delighted to answer your questions about my school.","Overall, I think that our rules are quite reasonable because they help to make the school well-organised.","I hope my answers are helpful."]}],"tips":["Trả lời theo đúng thứ tự câu hỏi của người gửi.","Mỗi chủ đề một đoạn ngắn để người đọc dễ tìm thông tin.","Không cần ghi nhớ máy móc: dùng cụm từ mẫu để tổ chức ý của chính bạn."]};
LBC['5.7']={"obj":["Thảo luận một moral dilemma, đưa ý kiến có lý do và phản hồi lịch sự","Thu âm podcast nhóm và nghe lại, phản hồi","Phân biệt fact và opinion","Viết bản tường trình (statement) theo trình tự thời gian, ngôi thứ nhất"],"vocab":[["in confidence","một cách bí mật, tin tưởng","phr"],["zero tolerance","không khoan nhượng","n"],["cyber-bullying","bắt nạt trên mạng","n"],["statement","bản tường trình, lời khai","n"],["chronological order","theo trình tự thời gian","n"],["fact","sự thật","n"],["opinion","ý kiến cá nhân","n"]],"gram":[{"t":"Agreeing, acknowledging, disagreeing politely","r":"Đồng tình: I agree with you about … / I think you’re right … Công nhận: I see your point … / That’s a good point … Phản biện lịch sự: I can see what you mean, but … Tự sửa: What I meant to say was … / Did you mean to say …?","ex":["I see your point, but …","I can see what you mean, but …","What I meant to say was …"]},{"t":"Writing a statement","r":"Chronological order · facts, not opinions · don’t invent details · report speech accurately · first person (I / my).","ex":["I woke up at around midnight and smelled smoke."]}],"tips":["Không cần lo nếu ngập ngừng hoặc mắc lỗi khi nói: tự sửa hoặc hỏi lại.","Statement chỉ dùng chi tiết có trong bài báo, không tự thêm nguyên nhân đám cháy, lời thoại, địa điểm.","Phần thu âm podcast làm ngoài web (điện thoại hoặc máy thu); web chỉ giúp chuẩn bị và phản hồi."]};
LBC['5.8']={"obj":["Hiểu giới thiệu sách Humankind và mục đích của tác giả","Đọc/nghe đoạn trích và tìm cách các cậu bé sống sót","Thảo luận vì sao các cậu bé đặt ra quy tắc và điều đó nói gì về bản chất con người","Viết đoạn miêu tả ngày về Tonga, dùng reported speech (They told me that …)"],"vocab":[["memoirs","hồi ký","n"],["commune","cộng đồng sống chung, chia sẻ công việc và tài nguyên","n"],["hollowed-out","đục rỗng ruột","adj"],["tend","chăm sóc, (ở đây) giữ lửa cháy","v"],["draw up","lập (kế hoạch) bằng văn bản","v"],["roster","bảng phân công","n"],["quarrel","cãi nhau","v"],["squabblers","những người đang cãi vã","n"],["makeshift","tạm bợ nhưng đủ dùng","adj"],["driftwood","gỗ trôi dạt","n"],["salvage","cứu vớt (đồ) khỏi sự phá hủy","v"],["lift (someone’s) spirits","làm ai vui lên","phr"],["frantic","cuống cuồng, tuyệt vọng","adj"],["fall apart","vỡ ra thành từng mảnh","v"],["in peak condition","trong tình trạng thể chất tuyệt vời","phr"],["jubilant","vui sướng tột độ","adj"],["turn out","đến xem, đến tham dự","v"],["commission","đặt (tàu) chuẩn bị đưa vào sử dụng","v"],["grant","trao, cho","v"]],"gram":[{"t":"Reported speech in a newspaper interview","r":"Kể lại điều người khác nói: They told me that + past tense (past simple / past perfect).","ex":["They told me that they had drifted for eight days without food or water.","They said that the fire never went out."]}],"tips":["Phần nghe Track 37 đã được thay bằng video CBS News – 60 Minutes (13 phút); đoạn trích Chapter 2 vẫn ở trang 139–140 trong sách.","Câu hỏi 3c (chuyện gì xảy ra khi các cậu bé về nhà) có trang tiếp theo trả lời: sách có đoạn kể về ngày trở về.","Chỉ dùng chi tiết có trong đoạn trích, không bịa thêm."]};
RDT['5.0']={"t":"School rules (Listening)","h":"<p>Bài này dựa trên <b>bài nghe phỏng vấn học sinh</b> ở Student’s Book, pp. 122–123 (Exercises 1–2). Hãy nghe audio của sách; web không tự tạo transcript hay đáp án nghe chính thức.</p>","n":"Câu trả lời của bạn được lưu để đối chiếu với audio."};
RDT['5.1']={"t":"Run your home like a business","h":"<p>Đọc bài báo <b>“Run your home like a business”</b> ở Learner’s Book, pp. 124–125: gia đình Eva Jarlsdotter, chồng Mattias và ba con ở Stockholm áp dụng phương pháp <b>kaizen</b> để tổ chức cuộc sống gia đình. Hãy đọc để tìm chi tiết cho từng câu hỏi; web không điền thay các chi tiết chưa kiểm tra trong bài đọc đầy đủ.</p>","n":"Câu trả lời dựa trên bài báo trong sách."};
RDT['5.2']={"t":"House rules (Listening)","h":"<p>Bài này dùng <b>audio Track 34 và 35</b> của sách (Learner’s Book, pp. 126–127, Exercises 1, 3 và 5). Web không tự tạo transcript hay đáp án nghe chính thức.</p>","n":"Câu trả lời của bạn được lưu để đối chiếu với audio."};
RDT['5.3']={"t":"Doing the right thing","h":"<p>Đọc ba bài chia sẻ của <b>Brandon</b>, <b>Rona</b> và <b>Bella</b> ở Learner’s Book, pp. 128–129. Hãy đọc từng tình huống và tìm bằng chứng trong văn bản gốc; các lựa chọn thái độ trên web chỉ là gợi ý diễn giải, không phải đáp án chính thức.</p>","n":"Nghe Track 36 từ audio của sách."};
RDT['5.4']={"t":"Rights and responsibilities","h":"<p>Đọc danh sách <b>“In the UK …”</b> ở Learner’s Book, pp. 130–131 (từ 12 đến 18 tuổi). Đây là nội dung học tập trích từ sách, không phải thông tin pháp lý cập nhật. Với phần Việt Nam, bạn tự tra cứu và ghi nguồn, web không điền độ tuổi giúp.</p>","n":"Danh sách UK dựa trên sách."};
RDT['5.5']={"t":"What happened?","h":"<p>Đọc hai lời khai ở Learner’s Book, trang 132: <b>Witness A (the driver)</b> và <b>Witness B (the person on the pavement)</b>. Hãy đọc kỹ, so sánh chi tiết, và làm Exercise 3 ở trang 133. Bài này không có phần nghe.</p>","n":"Nội dung dựa trên Learner’s Book; web chỉ hỗ trợ."};
RDT['5.6']={"t":"Improve your writing: an email","h":"<p>Đọc email của <b>Isabel</b> (trang 134) và thư trả lời của <b>Anisha</b> (trang 135) ở Learner’s Book. Chú ý giọng văn, cách chia đoạn và các cụm diễn đạt lịch sự. Sau đó viết email trả lời Isabel về trường của bạn (Exercise 4).</p>","n":"Nội dung email dựa trên Learner’s Book."};
RDT['5.7']={"t":"Project challenge","h":"<p>Hai dự án ở Learner’s Book, pp. 136–137: <b>Project 1</b> — thu âm podcast thảo luận một moral dilemma; <b>Project 2</b> — viết statement của <b>Chantale Adebayo</b> gửi cảnh sát từ góc nhìn của em ấy (bài báo “Teenage girl saves family from fire”, trang 137). Đọc bài báo và dilemma trong sách trước khi làm.</p>","n":"Nội dung dựa trên Learner’s Book; web chỉ hỗ trợ."};
RDT['5.8']={"t":"Non-fiction: Humankind","h":"<p>Đọc giới thiệu <b>Humankind</b> (Rutger Bregman) ở Learner’s Book, p. 138, đoạn trích <b>Chapter 2</b> (p. 139, Track 37) và đoạn <b>trở về Tonga</b> (p. 140). Câu chuyện có thật: sáu cậu bé Tonga, đảo Ata, Captain Peter Warner.</p>","n":"Học sinh đọc/nghe văn bản trong sách; web chỉ hỗ trợ."};
